import sys

class N:
    __slots__ = ('v', 'nxt')
    def __init__(self, v=0, nxt=None):
        self.v = v; self.nxt = nxt

def to_list(head):
    out = []
    while head:
        out.append(head.v); head = head.nxt
    return out

def swap_pair(node):
    if not node or not node.nxt:
        return node
    nxt = node.nxt
    node.nxt = swap_pair(nxt.nxt)
    nxt.nxt = node
    return nxt

def swap_best(values):
    head = None
    for v in reversed(values):
        head = N(v, head)
    return to_list(swap_pair(head))

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        print(); sys.exit(0)
    n = int(data[0])
    vals = list(map(int, data[1:1 + n]))
    print(' '.join(map(str, swap_best(vals))))
